 ''product.save.effects''::character varying, ''recharge.paid.shipping''::character varying, ''membership.paid.shipping''::character varying, ''membership.settled''::character varying, ''membership.pay.success.notice''::character varying])::text[])))','CHECK (((event_type)::text = ANY ((ARRAY[''order.paid''::character varying, ''order.delivery.notice''::character varying, ''order.refund.refused.notice''::character varying, ''order.second_card.advent.notice''::character varying, ''order.second_card.expired.notice''::character varying, ''withdrawal.approved.notice''::character varying, ''withdrawal.refused.notice''::character varying, ''withdrawal.applied.notice''::character varying, ''withdrawal.staff.refresh''::character varying, ''order.presale.fulfillment''::character varying, ''order.pink.success.notice''::character varying, ''product.stock.effects''::character varying, ''product.recycle.effects''::character varying, ''product.save.effects''::character varying, ''recharge.paid.shipping''::character varying, ''membership.paid.shipping''::character varying, ''order.pay.success.notice''::character varying, ''membership.settled''::character varying, ''membership.pay.success.notice''::character varying])::text[])))','CHECK (((event_type)::text = ANY ((ARRAY[''order.paid''::character varying, ''order.delivery.notice''::character varying, ''order.refund.refused.notice''::character varying, ''order.second_card.advent.notice''::character varying, ''order.second_card.expired.notice''::character varying, ''withdrawal.approved.notice''::character varying, ''withdrawal.refused.notice''::character varying, ''withdrawal.applied.notice''::character varying, ''withdrawal.staff.refresh''::character varying, ''order.presale.fulfillment''::character varying, ''order.pink.success.notice''::character varying, ''product.stock.effects''::character varying, ''product.recycle.effects''::character varying, ''product.save.effects''::character varying, ''recharge.paid.shipping''::character v