DO $recharge_paid_subject$
DECLARE d text; old_comment text; row_count integer; byte_count bigint; oversized boolean;
BEGIN
 SELECT pg_catalog.pg_get_constraintdef(oid,false),pg_catalog.obj_description(oid,'pg_constraint') INTO d,old_comment
  FROM pg_catalog.pg_constraint WHERE conrelid='public.order_notification_delivery'::regclass AND conname='ond_subject_ck';
 IF d='CHECK ((((subject_domain IS NULL) AND (subject_id IS NULL) AND ((event_key)::text !~~ ''membership.pay.success.notice:%''::text) AND ((event_key)::text !~~ ''recharge.pay.success.notice:%''::text) AND (((withdrawal_id IS NULL) AND (order_id IS NOT NULL)) OR ((withdrawal_id IS NOT NULL) AND (withdrawal_id > 0) AND (order_id IS NULL)))) OR ((subject_domain IS NOT NULL) AND (subject_id IS NOT NULL) AND ((subject_domain)::text = ANY ((ARRAY[''recharge''::character varying, ''membership''::character varying])::text[])) AND (subject_id > 0) AND (order_id IS NULL) AND (withdrawal_id IS NULL) AND ((channel)::text = ''wechat_shipping''::text) AND ((notice_mark)::text = ''paid_virtual_shipping''::text) AND ((event_key)::text = (((subject_domain)::text || ''.paid.shipping:''::text) || (subject_id)::text))) OR ((subject_domain IS NOT NULL) AND ((subject_domain)::text = ''membership''::text) AND (subject_id IS NOT NULL) AND (subject_id > 0) AND (order_id IS NULL) AND (withdrawal_id IS NULL) AND ((channel)::text = ANY ((ARRAY[''sms''::character varying, ''wechat_official''::character varying, ''wechat_routine''::character varying])::text[])) AND ((notice_mark)::text = ''order_pay_success''::text) AND ((event_key)::text = (''membership.pay.success.notice:''::text || (subject_id)::text))) OR ((subject_domain IS NOT NULL) AND ((subject_domain)::text = ''recharge''::text) AND (subject_id IS NOT NULL) AND (subject_id > 0) AND (order_id IS NULL) AND (withdrawal_id IS NULL) AND ((channel)::text = ANY ((ARRAY[''sms''::character varying, ''wechat_official''::character varying, ''wechat_routine''::character varying])::text[])) AND ((notice_mark)::text = ''recharge_success''::text) AND ((event_key)::text = (''recharge.pay.success.notice:''::text || (subject_id)::text)))))' THEN RETURN; END IF;
 IF d IS DISTINCT FROM 'CHECK ((((subject_domain IS NULL) AND (subject_id IS NULL) AND ((event_key)::text !~~ ''membership.pay.success.notice:%''::text) AND (((withdrawal_id IS NULL) AND (order_id IS NOT NULL)) OR ((withdrawal_id IS NOT NULL) AND (withdrawal_id > 0) AND (order_id IS NULL)))) OR ((subject_domain IS NOT NULL) AND (subject_id IS NOT NULL) AND ((subject_domain)::text = ANY ((ARRAY[''recharge''::character varying, ''membership''::character varying])::text[])) AND (subject_id > 0) AND (order_id IS NULL) AND (withdrawal_id IS NULL) AND ((channel)::text = ''wechat_shipping''::text) AND ((notice_mark)::text = ''paid_virtual_shipping''::text) AND ((event_key)::text = (((subject_domain)::text || ''.paid.shipping:''::text) || (subject_id)::text))) OR ((subject_domain IS NOT NULL) AND ((subject_domain)::text = ''membership''::text) AND (subject_id IS NOT NULL) AND (subject_id > 0) AND (order_id IS NULL) AND (withdrawal_id IS NULL) AND ((channel)::text = ANY ((ARRAY[''sms''::character varying, ''wechat_official''::character varying, ''wechat_routine''::character varying])::text[])) AND ((notice_mark)::text = ''order_pay_success''::text) AND ((event_key)::text = (''membership.pay.success.notice:''::text || (subject_id)::text)))))' OR pg_catalog.octet_length(old_comment)>4096 THEN
  RAISE EXCEPTION 'Recharge notice subject predecessor drift';
 END IF;
 SELECT count(*)::integer,COALESCE(sum(pg_column_size(t)),0),COALESCE(bool_or(pg_column_size(t)>1048576),false)
  INTO row_count,byte_count,oversized FROM (SELECT * FROM public.order_notification_delivery LIMIT 10001) t;
 IF row_count>10000 OR byte_count>16777216 OR oversized THEN RAISE EXCEPTION 'Recharge notice delivery maintenance row budget exceeded'; END IF;
 ALTER TABLE public.order_notification_delivery DROP CONSTRAINT ond_subject_ck;
 ALTER TABLE public.order_notification_delivery ADD CONSTRAINT ond_subject_ck CHECK (
 (subject_domain IS NULL AND subject_id IS NULL AND event_key NOT LIKE 'membership.pay.success.notice:%' AND event_key NOT LIKE 'recharge.pay.success.notice:%' AND
   ((withdrawal_id IS NULL AND order_id IS NOT NULL) OR (withdrawal_id IS NOT NULL AND withdrawal_id>0 AND order_id IS NULL)))
 OR (subject_domain IS NOT NULL AND subject_id IS NOT NULL AND subject_domain IN ('recharge','membership')
   AND subject_id>0 AND order_id IS NULL AND withdrawal_id IS NULL AND channel='wechat_shipping' AND notice_mark='paid_virtual_shipping'
   AND event_key=subject_domain::text || '.paid.shipping:'::text || subject_id::text)
 OR (subject_domain IS NOT NULL AND subject_domain='membership' AND subject_id IS NOT NULL AND subject_id>0 AND order_id IS NULL AND withdrawal_id IS NULL
   AND channel IN ('sms','wechat_official','wechat_routine') AND notice_mark='order_pay_success'
   AND event_key='membership.pay.success.notice:'::text || subject_id::text)
 OR (subject_domain IS NOT NULL AND subject_domain='recharge' AND subject_id IS NOT NULL AND subject_id>0
   AND order_id IS NULL AND withdrawal_id IS NULL AND channel IN ('sms','wechat_official','wechat_routine')
   AND notice_mark='recharge_success' AND event_key='recharge.pay.success.notice:'::text || subject_id::text)
);
 IF old_comment IS NOT NULL THEN EXECUTE pg_catalog.format('COMMENT ON CONSTRAINT ond_subject_ck ON public.order_notification_delivery IS %L',old_comment); END IF;
END
$recharge_paid_subject$;
